const companyForest: RoleNode[] = [
  {
    role: "company_owner",
    children: [
      {
        role: "company_manager",
        permissions: ["update_organization_company", "manage_members_company"],
        children: [
          { role: "company_standard", permissions: ["read_organization_company", "read_meteor_company"] },
        ],
      },
      { role: "company_billing", permissions: ["read_organization_company", "manage_billing_company"] },
    ],
  },
];

export const forests: Record<string, RoleNode[]> = { company: companyForest };

export const permissions = registerPermissions([
  accountBaselinePermissions,
  companyPermissions,
  creditsPermissions,
]);
export const { roles } = registerForests({ accountBaseline, forests });
export const accessControlConfig = { permissions, accountBaseline, forests };
